"""Compare patches generated by different LLM models.

This script analyzes patches generated by generate_regen_from_tests.py across different models,
allowing you to compare performance, costs, and results.

Usage:
  uv run python scripts/compare_model_patches.py \
      Instagram__MonkeyType.70c3acf6 \
      --compare_models

  uv run python scripts/compare_model_patches.py \
      Instagram__MonkeyType.70c3acf6 \
      --model_dirs logs/bug_gen/Instagram__MonkeyType.70c3acf6/ollama_gpt_oss_120b logs/bug_gen/Instagram__MonkeyType.70c3acf6/gpt_4
"""

import argparse
import json
import logging
from collections import defaultdict
from pathlib import Path
from typing import Any, Dict, List, Tuple

from swesmith.constants import PREFIX_BUG, PREFIX_METADATA

logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO)


def _collect_metadata_files(log_dir: Path) -> Dict[str, Dict[str, Any]]:
    """Recursively collect all metadata files from a log directory.
    
    Returns a dict mapping instance_id -> metadata
    """
    metadata_map = {}
    
    for meta_file in log_dir.rglob(f"{PREFIX_METADATA}__*.json"):
        try:
            data = json.loads(meta_file.read_text())
            # Try to extract instance_id from the parent path structure
            # For individual: .../file__path/attemptN/func_hash/
            # For combined: .../combined/attemptN/base_hash/
            
            relative_path = meta_file.relative_to(log_dir)
            parts = relative_path.parts
            
            # Create a unique key for tracking
            instance_key = str(relative_path)
            metadata_map[instance_key] = data
        except Exception as e:
            logger.warning(f"Failed to load metadata from {meta_file}: {e}")
            continue
    
    return metadata_map


def _collect_patch_files(log_dir: Path) -> Dict[str, Path]:
    """Recursively collect all patch files from a log directory.
    
    Returns a dict mapping instance_id -> patch file path
    """
    patch_map = {}
    
    for patch_file in log_dir.rglob(f"{PREFIX_BUG}__*.diff"):
        relative_path = patch_file.relative_to(log_dir)
        instance_key = str(relative_path)
        patch_map[instance_key] = patch_file
    
    return patch_map


def _load_validation_reports(repo: str, model_ids: List[str]) -> Dict[str, Dict[str, Any]]:
    """Load validation reports for each model.
    
    Returns dict mapping model_id -> validation_data
    """
    run_val_dir = Path("logs/run_validation") / repo
    validation_data = {}
    
    for model_id in model_ids:
        model_results = {}

        # Prefer model-scoped validation logs, fallback to legacy repo-scoped logs.
        model_scoped_dir = run_val_dir / model_id
        search_dir = model_scoped_dir if model_scoped_dir.exists() else run_val_dir
        for report_file in search_dir.rglob("report.json"):
            try:
                report = json.loads(report_file.read_text())
                instance_id = report_file.parent.name
                if search_dir == run_val_dir and f"__model_{model_id}__" not in instance_id:
                    continue
                model_results[instance_id] = report
            except Exception as e:
                logger.warning(f"Failed to load validation report from {report_file}: {e}")
                continue
        
        validation_data[model_id] = model_results
    
    return validation_data


def compare_models(repo: str, model_dirs: List[str] | None = None) -> None:
    """Compare patches across different models.
    
    Args:
        repo: Repository identifier
        model_dirs: List of model directory paths to compare. If None, scan logs/bug_gen/{repo}
    """
    bug_gen_dir = Path("logs/bug_gen") / repo
    
    if model_dirs:
        # Use provided model directories
        model_paths = [Path(d) for d in model_dirs]
    else:
        # Auto-discover model directories
        model_paths = [d for d in bug_gen_dir.iterdir() if d.is_dir()]
    
    if not model_paths:
        logger.error(f"No model directories found in {bug_gen_dir}")
        return
    
    logger.info(f"Comparing models: {[p.name for p in model_paths]}")
    
    # Collect data from each model
    model_data = {}
    for model_dir in model_paths:
        model_id = model_dir.name
        logger.info(f"Loading data for model: {model_id}")
        
        metadata = _collect_metadata_files(model_dir)
        patches = _collect_patch_files(model_dir)
        
        model_data[model_id] = {
            "metadata": metadata,
            "patches": patches,
            "total_patches": len(patches),
            "total_metadata": len(metadata),
        }

    validation_data = _load_validation_reports(repo, list(model_data.keys()))
    
    # Calculate statistics
    logger.info("\n" + "="*80)
    logger.info("COMPARISON SUMMARY")
    logger.info("="*80)
    
    total_costs = defaultdict(float)
    strategy_counts = defaultdict(lambda: defaultdict(int))
    
    for model_id, data in model_data.items():
        logger.info(f"\n{model_id}:")
        logger.info(f"  Total patches: {data['total_patches']}")
        logger.info(f"  Total metadata: {data['total_metadata']}")
        model_validation = validation_data.get(model_id, {})
        logger.info(f"  Validation reports: {len(model_validation)}")
        
        total_cost = 0.0
        strategies = defaultdict(int)
        
        for key, metadata in data["metadata"].items():
            cost = metadata.get("cost", 0.0)
            total_cost += cost
            
            strategy = metadata.get("strategy", "unknown")
            strategies[strategy] += 1
            strategy_counts[model_id][strategy] += 1
        
        total_costs[model_id] = total_cost
        logger.info(f"  Total cost: ${total_cost:.4f}")
        logger.info(f"  Strategies: {dict(strategies)}")

        if model_validation:
            timeout_count = sum(1 for r in model_validation.values() if r.get("timed_out"))
            f2p_nonempty = sum(
                1
                for r in model_validation.values()
                if isinstance(r.get("FAIL_TO_PASS"), list) and len(r.get("FAIL_TO_PASS")) > 0
            )
            logger.info(
                f"  Validation outcomes: timed_out={timeout_count}, fail_to_pass_nonempty={f2p_nonempty}"
            )
    
    # Compare costs
    logger.info("\n" + "="*80)
    logger.info("COST COMPARISON")
    logger.info("="*80)
    
    for model_id in sorted(total_costs.keys()):
        cost = total_costs[model_id]
        logger.info(f"{model_id}: ${cost:.4f}")
    
    if total_costs:
        min_model = min(total_costs, key=total_costs.get)
        max_model = max(total_costs, key=total_costs.get)
        logger.info(f"\nCheapest: {min_model} (${total_costs[min_model]:.4f})")
        logger.info(f"Most expensive: {max_model} (${total_costs[max_model]:.4f})")
    
    # Compare counts
    logger.info("\n" + "="*80)
    logger.info("PATCH COUNT COMPARISON")
    logger.info("="*80)
    
    for model_id in sorted(model_data.keys()):
        count = model_data[model_id]["total_patches"]
        logger.info(f"{model_id}: {count} patches")
    
    # Show details
    logger.info("\n" + "="*80)
    logger.info("DETAILED METADATA")
    logger.info("="*80)
    
    for model_id, data in model_data.items():
        logger.info(f"\n{model_id} metadata samples (first 5):")
        
        for i, (key, metadata) in enumerate(list(data["metadata"].items())[:5]):
            logger.info(f"  [{i+1}] {key}")
            logger.info(f"      strategy: {metadata.get('strategy', 'N/A')}")
            logger.info(f"      model: {metadata.get('model', 'N/A')}")
            logger.info(f"      cost: ${metadata.get('cost', 0.0):.4f}")


def list_model_dirs(repo: str) -> None:
    """List all available model directories for a repository."""
    bug_gen_dir = Path("logs/bug_gen") / repo
    
    if not bug_gen_dir.exists():
        logger.error(f"Bug gen directory not found: {bug_gen_dir}")
        return
    
    model_dirs = [d for d in bug_gen_dir.iterdir() if d.is_dir()]
    
    if not model_dirs:
        logger.info(f"No model directories found in {bug_gen_dir}")
        return
    
    logger.info(f"Available model directories for {repo}:")
    for model_dir in sorted(model_dirs):
        patches = len(list(model_dir.rglob(f"{PREFIX_BUG}__*.diff")))
        logger.info(f"  {model_dir.name} ({patches} patches)")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(
        description="Compare patches generated by different LLM models."
    )
    parser.add_argument("repo", type=str, help="Repository identifier")
    parser.add_argument(
        "--compare_models",
        action="store_true",
        help="Compare all models in logs/bug_gen/{repo}",
    )
    parser.add_argument(
        "--model_dirs",
        nargs="+",
        help="Specific model directories to compare (paths)",
    )
    parser.add_argument(
        "--list",
        action="store_true",
        help="List all available model directories",
    )
    
    args = parser.parse_args()
    
    if args.list:
        list_model_dirs(args.repo)
    elif args.compare_models or args.model_dirs:
        compare_models(args.repo, model_dirs=args.model_dirs)
    else:
        parser.print_help()
